import os, re
from collections import defaultdict

ROOT = "/bench/repo"

# Data layer: store tree + proto/gen/store
DATA_LAYER_PREFIXES = [
    os.path.join(ROOT, "store"),
    os.path.join(ROOT, "proto", "gen", "store"),
]

def is_data_layer(path):
    for p in DATA_LAYER_PREFIXES:
        if path.startswith(p + os.sep) or path == p:
            return True
    return False

def go_package_dir(filepath):
    return os.path.dirname(filepath)

def package_key(filepath):
    """Return package identifier as relative path from repo root."""
    d = go_package_dir(filepath)
    return os.path.relpath(d, ROOT)

# Persistent entity types (Go structs mapping to DB tables)
ENTITIES = [
    "User", "UserSetting", "Memo", "MemoRelation", "Attachment",
    "IdentityProvider", "Inbox", "Reaction", "MemoShare", "UserIdentity",
    "InstanceSetting",
]

# Patterns for store.Entity references
entity_patterns = {
    e: re.compile(r'\bstore\.' + e + r'\b')
    for e in ENTITIES
}

# Also count storepb proto entity-related types if used as standalone
PROTO_ENTITIES = []  # we'll focus on Go store structs first

entity_packages = {e: set() for e in ENTITIES}

for dirpath, dirnames, filenames in os.walk(ROOT):
    # skip .git
    if '.git' in dirnames:
        dirnames.remove('.git')
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        fp = os.path.join(dirpath, fn)
        if is_data_layer(fp):
            continue
        try:
            with open(fp, 'r', errors='ignore') as f:
                content = f.read()
        except:
            continue
        # Only count files that import store package (direct entity refs use store.X)
        if 'github.com/usememos/memos/store' not in content and 'store.' not in content:
            continue
        pkg = package_key(fp)
        for e, pat in entity_patterns.items():
            if pat.search(content):
                entity_packages[e].add(pkg)

print("=== Distinct packages referencing store.<Entity> (outside data layer) ===")
